def publish(bus, topic, payload):
  # Get subscribers for the given topic, if any
  subscribers = bus.get("subscribers", {}).get(topic, [])
  # Track which subscribers were called
  called = []

  # Try each subscriber in order
  for func in subscribers:
    try:
      func(payload)
      called.append(True)
    except Exception:
      # Ignore errors, keep going
      continue

  # Check for wildcard subscribers
  wildcard_subs = bus.get("wildcard_subs", {}).get(topic, [])
  for func in wildcard_subs:
    try:
      func(topic, payload)
      called.append(True)
    except Exception:
      # Ignore errors, keep going
      continue

  # Count how many deliveries succeeded
  successful = len(called)

  # If no deliveries happened, record the event as undelivered
  if successful == 0:
    bus.setdefault("dead_letters", []).append((topic, payload))

  return successful
```

