def publish(bus, topic, payload):
  # Get subscribers for the given topic, if any
  subscribers = bus.subscribers.get(topic)
  if not subscribers:
    # No subscribers means the event is ignored
    return 0

  # List to track successful deliveries
  successes = 0

  # Step 1: Call each subscriber in order with just the payload
  for func in subscribers:
    try:
      func(payload)
      successes += 1
    except Exception:
      # If a subscriber fails, ignore it
      continue

  # Step 2: Call wildcard subscribers (topic "*") in order
  wildcard_subs = bus.subscribers.get("*")
  if wildcard_subs:
    for func in wildcard_subs:
      try:
        func(topic, payload)
        successes += 1
      except Exception:
        # Still ignore if a wildcard subscriber fails
        continue

  # Step 3: If no one succeeded, mark the event as undelivered
  if successes == 0:
    bus.dead_letters.append((topic, payload))

  # Return how many deliveries were successful
  return successes
