def fetch_all(client):
    items = []
    cursor = "START"
    while True:
        response = client.fetch_page(cursor)
        if "items" not in response:
            # If the response doesn't have 'items', it might be an error
            # but according to the documentation, this shouldn't happen
            break
        for item in response["items"]:
            if not item.get("deleted", False):
                items.append(item)
        next_cursor = response.get("next")
        if next_cursor is None:
            break
        cursor = next_cursor
    return items
```

