def process_next(queue, handler):
    while True:
        job = queue.pop()
        if job is None:
            return None
        if handler(job):
            queue.ack(job["id"])
            return "done"
        else:
            job["attempts"] += 1
            if job["attempts"] >= 3:
                return "failed"
            else:
                queue.push(job)
                return "retry"
```

